let joinedContext = "";
let citationBlock = "";
let citationList = [];
let retrievalFailed = false;

const selectedAgent = $json.selected_agent;
const requiresRag = $json.requires_rag;
let predictedIntents = [];
try {
  predictedIntents = $json.predicted_intents || $('Parse Planner Decision').first().json.predicted_intents || [];
} catch (e) {
  predictedIntents = [];
}

if (requiresRag) {
  joinedContext = $json.joined_context || "";
  citationBlock = $json.citation_block || "";
  citationList = Array.isArray($json.citation_list) ? $json.citation_list : [];
  retrievalFailed = ($json.retrieval_failed === true || $json.retrieval_failed === "true");
}

const securityNode = $('Security & Sanitization Gate').first().json.body;
const userPrompt = securityNode.prompt;
const overrides = securityNode.prompt_overrides || {};

let activePrompts = {};
try {
  activePrompts = $('Fetch Active Prompts').first().json;
} catch (e) {
  activePrompts = {};
}

const getPrompt = (agentName, defaultVal) => {
  return overrides[agentName] || activePrompts[agentName] || defaultVal;
};

let finalAgent = selectedAgent;
let finalRequires = requiresRag;
if (securityNode.agent_mode && securityNode.agent_mode !== "default" && securityNode.agent_mode !== "") {
  finalAgent = securityNode.agent_mode;
  if (securityNode.agent_mode !== "default") {
    finalRequires = true;
  }
}

// NEW RULE: if RAG is required but retrieval failed (no matching documents found in RAG),
// push to "no_intent" to present options to the user.
if (finalRequires && retrievalFailed) {
  finalAgent = "no_intent";
}

// Never block/reject using fallback text - allow external LLM intelligence for all modules
let ragGuardrailTriggered = false;

let effectiveCitationBlock = citationBlock;
let effectiveCitationList = citationList;
if (!citationBlock || citationBlock.trim() === "" || retrievalFailed) {
  effectiveCitationBlock = "- **Nguồn tham khảo:** Kiến thức mở rộng";
  effectiveCitationList = [{ document: "Kiến thức mở rộng", lesson: "", position: "", volume: "" }];
}

const RAG_RULE_PREFIX = "HƯỚNG DẪN SỬ DỤNG NGỮ CẢNH & KIẾN THỨC MỞ RỘNG:\n" +
  "- Bạn ĐƯỢC PHÉP truy cập và sử dụng triệt để trí tuệ/kiến thức mở rộng của bản thân để giải đáp câu hỏi, tạo bộ bài tập hoặc giảng giải lý thuyết một cách sư phạm nhất.\n" +
  "- Nếu Ngữ cảnh SGK có thông tin, hãy ưu tiên tham khảo nội dung và độ khó từ SGK.\n" +
  "- Nếu Ngữ cảnh SGK không có hoặc không đầy đủ (hoặc retrieval không tìm thấy), hãy sử dụng kiến thức mở rộng chuyên môn để trả lời khéo léo và chính xác.\n\n" +
  "Ngữ cảnh tài liệu SGK (nếu có):\n" + joinedContext + "\n\n";

// --- Default Teacher ---
let defaultTeacherPrompt = "";
const baseDefaultTeacher = getPrompt('default_teacher', 'Bạn là một giáo viên tiểu học thân thiện, tận tụy và dịu dàng.');
if (finalRequires) {
  defaultTeacherPrompt = baseDefaultTeacher + "\n\n" + RAG_RULE_PREFIX +
    "Câu hỏi của người dùng:\n" + userPrompt +
    "\n\nYêu cầu câu trả lời:\n1. Trả lời thân thiện, giải thích từng bước logic toán học rõ ràng.\n2. Trả lời hoàn toàn bằng tiếng Việt.\n3. Cuối câu trả lời, in rõ phần trích dẫn nguồn theo đúng định dạng sau:\n\n---\n **Nguồn tham khảo:**\n" + effectiveCitationBlock;
} else {
  defaultTeacherPrompt = baseDefaultTeacher + " Hãy trò chuyện thân thiện, trả lời tự nhiên hoặc giải thích toán học đơn giản cho câu hỏi của người dùng.\n\n" +
    "LƯU Ý ĐẶC BIỆT KHI XỬ LÝ TỪ VÔ NGHĨA (SILLY WORDS):\n" +
    "- Nếu người dùng/học sinh nhập các từ gõ phím vô nghĩa, ký tự ngẫu nhiên không có ý nghĩa gì (ví dụ như 'kahsdgh', 'asdfgh', 'gjhgjg'...), tuyệt đối KHÔNG dùng từ 'Dạ' ở đầu câu, hãy phản hồi bằng câu hỏi dịu dàng, thân thiện và gần gũi (ví dụ: 'Thầy/Cô có thể giúp gì cho con nhỉ? Con có thể cho thầy/cô biết bài toán hay chủ đề con đang cần hỗ trợ không?').\n\n" +
    "Câu hỏi/Lời nhắn của người dùng:\n" + userPrompt + "\n\nYêu cầu:\n1. Trả lời thân thiện, ngọt ngào bằng tiếng Việt.\n2. Cuối câu trả lời, in trích dẫn:\n\n---\n **Nguồn tham khảo:**\n- **Nguồn tham khảo:** Kiến thức mở rộng";
}

// --- Barem Reviewer ---
const baseBarem = getPrompt('barem_review', 'Bạn là một giáo viên tiểu học thân thiện, tận tụy và công tâm. Nhiệm vụ của bạn là chấm điểm và nhận xét bài làm của học sinh dựa trên Barem điểm và đáp án chuẩn được cung cấp.');
const baremPrompt = baseBarem + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi/Yêu cầu chấm điểm (chứa Đề bài, Barem & Bài làm của học sinh):\n" + userPrompt +
  "\n\nHãy thực hiện chấm điểm và đưa ra nhận xét sư phạm chi tiết, ấm áp.\n\nQUAN TRỌNG: Chỉ in ra DUY NHẤT đối tượng JSON đúng schema đã mô tả ở trên. KHÔNG thêm lời dẫn, KHÔNG bọc trong khối ```json, KHÔNG tự in phần trích dẫn nguồn (hệ thống sẽ tự chèn).";

// --- Theory Explainer ---
const baseTheory = getPrompt('theory_explanation', 'Bạn là một giáo viên tiểu học có tài giảng dạy trực quan, sinh động. Nhiệm vụ của bạn là giải thích các định nghĩa, khái niệm toán học lớp 3 từ sách giáo khoa một cách dễ hiểu nhất.');
const theoryPrompt = baseTheory + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi của học sinh/phụ huynh về khái niệm lý thuyết:\n" + userPrompt +
  "\n\nGiải thích trực quan, gần gũi, dùng ví dụ thực tế cho trẻ em 8-9 tuổi.\n\nQUAN TRỌNG: Chỉ in ra DUY NHẤT đối tượng JSON đúng schema đã mô tả ở trên. KHÔNG thêm lời dẫn, KHÔNG bọc trong khối ```json, KHÔNG tự in phần trích dẫn nguồn (hệ thống sẽ tự chèn).";

// --- Exercise Generator ---
const baseExercise = getPrompt('exercise_generator', 'Bạn là một chuyên gia biên soạn tài liệu toán tiểu học. Nhiệm vụ của bạn là tạo ra các bài tập tự luyện mới dựa trên ngữ cảnh bài học trong sách giáo khoa.');
const exercisePrompt = baseExercise + "\n\n" + RAG_RULE_PREFIX +
  "Yêu cầu tạo bài tập của người dùng:\n" + userPrompt +
  "\n\nTạo bộ bài tập 3 mức độ (Nhận biết, Vận dụng, Vận dụng cao) phù hợp với học sinh lớp 3. Tham khảo độ khó từ SGK nếu có, hoặc dùng kiến thức mở rộng để soạn bộ bài tập chất lượng.\n\nQUAN TRỌNG: Chỉ in ra DUY NHẤT đối tượng JSON đúng schema đã mô tả ở trên. KHÔNG thêm lời dẫn, KHÔNG bọc trong khối ```json, KHÔNG tự in phần trích dẫn nguồn (hệ thống sẽ tự chèn).";

// --- Suggestive Tutor ---
const baseTutor = getPrompt('suggestive_tutor', 'Bạn là một Gia sư Toán Tiểu học có phương pháp dạy học tương tác, gợi mở (Socratic method). TUYỆT ĐỐI KHÔNG đưa ra lời giải đầy đủ hay đáp số cuối cùng ngay lập tức. Hãy dắt tay học sinh tự tìm ra đáp án.');
const tutorPrompt = baseTutor + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi cần gợi ý của học sinh:\n" + userPrompt +
  "\n\nHướng dẫn từng bước bằng câu hỏi gợi mở, không đưa đáp số trực tiếp.\n\nQUAN TRỌNG: Chỉ in ra DUY NHẤT đối tượng JSON đúng schema sau: {'guidance': '...', 'question_to_student': '...'}. KHÔNG thêm lời dẫn, KHÔNG bọc trong khối ```json, KHÔNG tự in phần trích dẫn nguồn (hệ thống sẽ tự chèn).";

// --- Direct Solver ---
const baseSolver = getPrompt('direct_solver', 'Bạn là một Trợ lý Giải Toán Tiểu học nhanh chóng và chính xác. Nhiệm vụ của bạn là đưa ra kết quả cuối cùng ngay lập tức, sau đó trình bày bài giải chi tiết theo đúng chuẩn sư phạm lớp 3.');
const solverPrompt = baseSolver + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi/Bài toán cần giải:\n" + userPrompt +
  "\n\n[Ans] Đưa ra đáp số nhanh trước, sau đó trình bày từng bước giải chi tiết.\n\nQUAN TRỌNG: Chỉ in ra DUY NHẤT đối tượng JSON đúng schema đã mô tả ở trên. KHÔNG thêm lời dẫn, KHÔNG bọc trong khối ```json, KHÔNG tự in phần trích dẫn nguồn (hệ thống sẽ tự chèn).";

return {
  prompt: userPrompt,
  joined_context: joinedContext,
  citation_block: effectiveCitationBlock,
  citation_list: effectiveCitationList,
  selected_agent: finalAgent,
  requires_rag: finalRequires,
  retrieval_failed: retrievalFailed,
  rag_guardrail_triggered: false,
  default_teacher_prompt: defaultTeacherPrompt,
  barem_prompt: baremPrompt,
  theory_prompt: theoryPrompt,
  exercise_prompt: exercisePrompt,
  tutor_prompt: tutorPrompt,
  solver_prompt: solverPrompt,
  predicted_intents: predictedIntents
};

let responseText = '';
let activeAgent = 'default';
const agents = ['Suggestive Tutor', 'Direct Solver', 'Default Teacher', 'Theory Explainer', 'Exercise Generator', 'Barem Reviewer'];
for (const agent of agents) {
  try {
    const nodeRes = $(agent).first().json;
    if (nodeRes && nodeRes.text) {
      responseText = nodeRes.text;
      activeAgent = agent;
      break;
    }
  } catch (e) {}
}

const webhookBody = $('Webhook').first().json.body || {};
const conversationId = webhookBody.conversation_id || '';

let parsedData = {};
function parseAgentJson(text) {
  const m = String(text || '').match(/\{[\s\S]*\}/);
  if (!m) return null;
  try {
    return JSON.parse(m[0]);
  } catch (e) {
    return null;
  }
}
const agentJson = parseAgentJson(responseText);
let jsonBranchUsed = false;

const agentKeyMap = {
  'Suggestive Tutor': 'suggestive_tutor',
  'Direct Solver': 'direct_solver',
  'Default Teacher': 'default_teacher',
  'Theory Explainer': 'theory_explanation',
  'Exercise Generator': 'exercise_generator',
  'Barem Reviewer': 'barem_review'
};
const mappedAgent = agentKeyMap[activeAgent] || 'default';

const typeMap = {
  'suggestive_tutor': 'suggestive_tutor',
  'direct_solver': 'direct_solver',
  'default_teacher': 'default_teacher',
  'theory_explanation': 'theory_explainer',
  'exercise_generator': 'exercise_generator',
  'barem_review': 'barem_reviewer',
  'default': 'default_teacher'
};
const responseType = typeMap[mappedAgent] || 'default_teacher';

if (mappedAgent === 'barem_review') {
  if (agentJson && (agentJson.score_rows || agentJson.total_score)) {
    jsonBranchUsed = true;
    const rows = Array.isArray(agentJson.score_rows) ? agentJson.score_rows : [];
    let table = '';
    if (rows.length) {
      table = '| Phần / Bước giải | Yêu cầu Barem | Bài làm của con | Điểm đạt được |\n| :--- | :--- | :--- | :--- |\n';
      table += rows.map(r => '| ' + [r.section, r.barem_requirement, r.student_work, r.score]
        .map(c => String(c == null ? '' : c).replace(/\|/g, '\\|').replace(/\n/g, ' ').trim())
        .join(' | ') + ' |').join('\n');
    }

    const greeting = String(agentJson.greeting || '').trim();
    const totalScore = String(agentJson.total_score || '').trim();
    const advice = String(agentJson.advice || '').trim();
    const encouragement = String(agentJson.encouragement || '').trim();

    parsedData = {
      greeting: greeting,
      score_rows: rows,
      total_score: totalScore,
      advice: advice,
      encouragement: encouragement
    };

    responseText = [
      greeting,
      table,
      totalScore ? '**Tổng điểm: ' + totalScore + '**' : '',
      advice ? '### Lời khuyên & Hướng dẫn sửa bài\n' + advice : '',
      encouragement
    ].filter(Boolean).join('\n\n').trim();
  } else {
    let greeting = '';
    let table = '';
    let totalScore = '';
    let advice = '';
    let encouragement = '';

    const lines = responseText.split('\n');
    let tableLines = [];
    let inTable = false;
    let beforeTableLines = [];
    let afterTableLines = [];

    for (let line of lines) {
      if (line.trim().startsWith('|')) {
        inTable = true;
        tableLines.push(line);
      } else {
        if (inTable) inTable = false;
        if (tableLines.length === 0) beforeTableLines.push(line);
        else afterTableLines.push(line);
      }
    }

    greeting = beforeTableLines.join('\n').trim();
    table = tableLines.join('\n').trim();
    const remainingText = afterTableLines.join('\n');

    const scoreRegex = /(?:Tổng điểm|Điểm số|Score)[:\s]*\**([0-9.,]+\s*\/\s*[0-9.,]+)\**/i;
    const match = remainingText.match(scoreRegex);
    if (match) {
      totalScore = match[1].trim();
    } else {
      const fracMatch = remainingText.match(/\b([0-9.,]+\s*\/\s*[0-9.,]+)\b/);
      if (fracMatch) totalScore = fracMatch[1].trim();
    }

    const adviceHeadings = [
      /###\s*Lời khuyên\s*&\s*Hướng dẫn\s*sửa\s*bài/i,
      /###\s*Hướng dẫn\s*sửa\s*bài/i,
      /###\s*Lời khuyên/i,
      /\*\*Lời khuyên\*\*/i
    ];

    let adviceIndex = -1;
    for (let r of adviceHeadings) {
      const idx = remainingText.search(r);
      if (idx !== -1) {
        adviceIndex = idx;
        break;
      }
    }

    advice = (adviceIndex !== -1) ? remainingText.substring(adviceIndex).trim() : remainingText.trim();

    const encouragementHeadings = [
      /###\s*Lời chúc\s*&\s*Động viên/i,
      /###\s*Động viên/i,
      /\*\*Lời chúc\*\*/i
    ];
    let encouragementIndex = -1;
    for (let r of encouragementHeadings) {
      const idx = advice.search(r);
      if (idx !== -1) {
        encouragementIndex = idx;
        break;
      }
    }

    if (encouragementIndex !== -1) {
      encouragement = advice.substring(encouragementIndex).trim();
      advice = advice.substring(0, encouragementIndex).trim();
    } else {
      const paragraphs = advice.split('\n\n');
      if (paragraphs.length > 1) {
        encouragement = paragraphs[paragraphs.length - 1].trim();
        advice = paragraphs.slice(0, paragraphs.length - 1).join('\n\n').trim();
      }
    }

    parsedData = {
      greeting: greeting,
      score_table: table,
      total_score: totalScore,
      advice: advice,
      encouragement: encouragement
    };
  }
} else if (mappedAgent === 'theory_explanation') {
  const ruleHasContent = agentJson && (Array.isArray(agentJson.rule_summary)
    ? agentJson.rule_summary.length > 0
    : !!agentJson.rule_summary);
  if (agentJson && (agentJson.concept || ruleHasContent)) {
    jsonBranchUsed = true;
    const concept = String(agentJson.concept || '').trim();
    const example = String(agentJson.example || '').trim();
    const challenge = String(agentJson.challenge || '').trim();

    const ruleIsList = Array.isArray(agentJson.rule_summary);
    const rule_summary = ruleIsList ? agentJson.rule_summary : String(agentJson.rule_summary || '').trim();
    const ruleText = ruleIsList
      ? rule_summary.map(r => {
          const term = String(r.term || '').trim();
          const definition = String(r.definition || '').trim();
          return '- ' + (term ? '**' + term + ':** ' : '') + definition;
        }).join('\n')
      : rule_summary;

    parsedData = {
      concept: concept,
      example: example,
      rule_summary: rule_summary,
      challenge: challenge
    };

    responseText = [
      concept ? '### Khái niệm đơn giản\n' + concept : '',
      example ? '### Ví dụ thực tế\n' + example : '',
      ruleText ? '### Tóm tắt quy tắc\n' + ruleText : '',
      challenge ? '### Thử thách nhỏ cho con\n' + challenge : ''
    ].filter(Boolean).join('\n\n').trim();
  } else {
    let concept = '';
    let example = '';
    let rule_summary = '';
    let challenge = '';

    const conceptMarkers = [/###\s*Khái niệm/i, /Khái niệm đơn giản/i];
    const exampleMarkers = [/###\s*Ví dụ/i, /Ví dụ thực tế/i];
    const ruleMarkers = [/###\s*Tóm tắt/i, /Tóm tắt quy tắc/i];
    const challengeMarkers = [/###\s*Thử thách/i, /Thử thách nhỏ/i];

    const sections = responseText.split(/(?=###|\*\*Khái niệm|\*\*Ví dụ|\*\*Tóm tắt|\*\*Thử thách)/g);

    for (let sec of sections) {
      let matched = false;
      for (let m of challengeMarkers) {
        if (sec.match(m)) { challenge = sec.trim(); matched = true; break; }
      }
      if (matched) continue;
      for (let m of ruleMarkers) {
        if (sec.match(m)) { rule_summary = sec.trim(); matched = true; break; }
      }
      if (matched) continue;
      for (let m of exampleMarkers) {
        if (sec.match(m)) { example = sec.trim(); matched = true; break; }
      }
      if (matched) continue;
      for (let m of conceptMarkers) {
        if (sec.match(m)) { concept = sec.trim(); matched = true; break; }
      }
      if (!matched && sec.trim()) {
        concept = concept ? concept + '\n\n' + sec.trim() : sec.trim();
      }
    }

    parsedData = {
      concept: concept.trim(),
      example: example.trim(),
      rule_summary: rule_summary.trim(),
      challenge: challenge.trim()
    };
  }
} else if (mappedAgent === 'exercise_generator') {
  if (agentJson && Array.isArray(agentJson.exercises)) {
    jsonBranchUsed = true;
    const list = agentJson.exercises;

    const exercises = list.map((e, i) => {
      const idx = e.index || (i + 1);
      const level = e.level ? ' (' + String(e.level).trim() + ')' : '';
      return '**Bài ' + idx + '**' + level + ': ' + String(e.question || '').trim();
    }).join('\n\n');

    const solutionText = (sol) => {
      if (!sol || typeof sol !== 'object') return String(sol || '').trim();
      const lines = (Array.isArray(sol.steps) ? sol.steps : []).map((s, k) => {
        const n = s.step || (k + 1);
        const title = s.title ? ' ' + String(s.title).trim() : '';
        const expr = s.expression ? '\n    ' + String(s.expression).trim() : '';
        const explain = s.explanation ? '\n    ' + String(s.explanation).trim() : '';
        return '- **Bước ' + n + ':**' + title + expr + explain;
      });
      let text = lines.join('\n');
      const conclusion = String(sol.conclusion || '').trim();
      if (conclusion) {
        text += (text ? '\n' : '') + '- **Kết luận/Đáp số:** ' + conclusion;
      }
      return text;
    };

    const solutions_hidden = list.map((e, i) => {
      const idx = e.index || (i + 1);
      return '<details>\n<summary>Xem gợi ý giải Bài ' + idx + '</summary>\n\n'
        + solutionText(e.solution) + '\n\n</details>';
    }).join('\n\n');

    parsedData = {
      exercises: list
    };

    responseText = (exercises + '\n\n' + solutions_hidden).trim();
  } else {
    let exercises = '';
    let solutions_hidden = '';

    const idx = responseText.indexOf('<details>');
    if (idx !== -1) {
      exercises = responseText.substring(0, idx).trim();
      solutions_hidden = responseText.substring(idx).trim();
    } else {
      exercises = responseText.trim();
    }

    parsedData = {
      exercises: exercises,
      solutions_hidden: solutions_hidden
    };
  }
} else if (mappedAgent === 'suggestive_tutor') {
  if (agentJson && (agentJson.guidance || agentJson.question_to_student)) {
    jsonBranchUsed = true;
    const guidance = String(agentJson.guidance || '').trim();
    const question_to_student = String(agentJson.question_to_student || '').trim();
    parsedData = {
      guidance: guidance,
      question_to_student: question_to_student
    };
    responseText = [guidance, question_to_student].filter(Boolean).join('\n\n').trim();
  } else {
    let guidance = responseText.trim();
    let question_to_student = '';
    const paragraphs = responseText.split('\n\n');
    if (paragraphs.length > 0) {
      const lastPara = paragraphs[paragraphs.length - 1].trim();
      if (lastPara.endsWith('?')) {
        question_to_student = lastPara;
      }
    }
    parsedData = {
      guidance: guidance,
      question_to_student: question_to_student
    };
  }
} else if (mappedAgent === 'direct_solver') {
  let quick_answer = '';
  let steps = [];
  let conclusion = '';
  let detailed_solution = '';

  const solverJsonOk = !!(agentJson && (agentJson.quick_answer || Array.isArray(agentJson.steps)));
  if (solverJsonOk) {
    jsonBranchUsed = true;
    quick_answer = String(agentJson.quick_answer || '').trim();
    steps = Array.isArray(agentJson.steps) ? agentJson.steps : [];
    conclusion = String(agentJson.conclusion || '').trim();

    const stepLines = steps.map((s, i) => {
      const idx = s.step || (i + 1);
      const title = s.title ? ' ' + String(s.title).trim() : '';
      const expr = s.expression ? '\n    ' + String(s.expression).trim() : '';
      const explain = s.explanation ? '\n    ' + String(s.explanation).trim() : '';
      return '- **Bước ' + idx + ':**' + title + expr + explain;
    });
    detailed_solution = stepLines.join('\n');
    if (conclusion) {
      detailed_solution += (detailed_solution ? '\n' : '') + '- **Kết luận/Đáp số:** ' + conclusion;
    }
    responseText = ('**' + quick_answer + '**\n\n' + detailed_solution).trim();
  } else {
    const lines = responseText.split('\n');
    if (lines.length > 0) {
      quick_answer = lines[0].trim();
      detailed_solution = lines.slice(1).join('\n').trim();
    } else {
      detailed_solution = responseText.trim();
    }
  }

  parsedData = solverJsonOk
    ? { quick_answer: quick_answer, steps: steps, conclusion: conclusion }
    : { quick_answer: quick_answer, steps: steps, conclusion: conclusion, detailed_solution: detailed_solution };
} else {
  // Default Teacher / General Response
  if (agentJson && (agentJson.message || agentJson.response)) {
    jsonBranchUsed = true;
    const msg = String(agentJson.message || agentJson.response || '').trim();
    const suggestedQuestions = Array.isArray(agentJson.suggested_questions) ? agentJson.suggested_questions : [];
    parsedData = {
      message: msg,
      suggested_questions: suggestedQuestions
    };
    responseText = msg;
  } else {
    parsedData = {
      message: responseText.trim()
    };
  }
}

// For ALL AGENTS: enable JSON payload format and construct reference fields: ref, references, citations
const JSON_AGENTS = ['barem_review', 'theory_explanation', 'exercise_generator', 'direct_solver', 'suggestive_tutor', 'default_teacher', 'default'];
const isJsonPayload = JSON_AGENTS.includes(mappedAgent);

let citationBlock = '';
