} catch (e) {}

let citationsObj = {};
citationList.forEach((c, idx) => {
  citationsObj[`ref${idx + 1}`] = c;
});

parsedData.citations = citationsObj;

// Citations are stored in data.citations, skip appending raw text to output

return {
  status: 'success',
  agent: mappedAgent,
  type: responseType,
  conversation_id: conversationId,
  format: 'json',
  output: responseText,
  data: parsedData
};

