- "no_intent": Chọn khi yêu cầu chứa từ khóa/khái niệm học tập có nghĩa nhưng chưa rõ ý định 50/50, nhập danh từ/khái niệm độc lập (ví dụ: "hình vuông", "chu vi", "phép cộng").
- "default": Trò chuyện xã giao thân thiện HOẶC khi người dùng nhập các từ gõ phím vô nghĩa / silly words (ví dụ: "kahsdgh", "asdfgh", ký tự ngẫu nhiên).

Quy tắc BẮT BUỘC khi chọn "no_intent":
- Khi selected_agent = "no_intent", bạn BẮT BUỘC phải đưa 2 đến 3 tùy chọn gợi ý khả thi nhất vào danh sách "predicted_intents" (ví dụ: ["theory_explanation", "exercise_generator", "suggestive_tutor"]).`;

const fullPlannerPrompt = `${plannerPromptTemplate}\n\nCâu hỏi/Yêu cầu của người dùng:\n${userPrompt}\n\nHãy trả về chính xác định dạng JSON sau (KHÔNG kèm văn bản ngoài JSON):\n{\n  "selected_agent": "tên_agent",\n  "predicted_intents": ["intent_1", "intent_2", "intent_3"],\n  "requires_rag": true | false\n}`;

const tagUuids = securityNode.tag_name_uuid || [];
const orgIds = securityNode.org_id || [];

// Execute BOTH HTTP requests concurrently in parallel using Promise.all
const [plannerResRaw, retrievalResRaw] = await Promise.all([
  this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:8080/api/llm',
    body: {
      prompt: fullPlannerPrompt
    },
    json: true
  }).catch(err => ({ text: "{}" })),

  this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:8080/api/retrieval',
    body: {
      text: userPrompt,
      tag_name_uuids: tagUuids,
      org_ids: orgIds,
      type: "doc",
      top_k: 3
    },
    json: true
  }).catch(err => ({ results: [] }))
]);

// --- Parse Planner Decision ---
let selectedAgent = "default";
let requiresRag = false;
let predictedIntents = [];
try {
  const text = plannerResRaw.text || "";
  const cleanText = text.replace(/```json/gi, "").replace(/```/gi, "").trim();
  const parsed = JSON.parse(cleanText);
  selectedAgent = parsed.selected_agent || "default";
  requiresRag = (parsed.requires_rag === true || parsed.requires_rag === "true");
  predictedIntents = parsed.predicted_intents || [];
} catch (e) {
  selectedAgent = "default";
  requiresRag = false;
  predictedIntents = [];
}

// --- Process Retrieval Results ---
const results = (retrievalResRaw.results || []).filter(r => r.distance === undefined || r.distance < 1.6);
const contextTexts = [];
const citations = [];
const citationList = [];
let retrievalFailed = false;

if (results.length === 0) {
  retrievalFailed = true;
} else {
  results.forEach((chunk, index) => {
    const meta = chunk.metadata || {};
    const physPage = meta.physical_page;
    const pdfPage = meta.pdf_page_number || (meta.pdf_page_index !== undefined ? meta.pdf_page_index + 1 : undefined);
    const pageStr = (physPage !== undefined && physPage !== -1) ? `Trang ${physPage}` : (pdfPage !== undefined ? `Trang PDF ${pdfPage}` : 'Trang chưa rõ');
    const lessonName = meta.lesson_name || 'Chưa rõ';
    const fileName = meta.file_name || 'SGK Toán 3';
    const volume = meta.volume || '1';
    contextTexts.push(`--- Đoạn ${index + 1}: ${fileName}, ${pageStr} ---\n${chunk.text}`);
    citations.push(`- **Tài liệu:** ${fileName} | **Bài học:** ${lessonName} | **Vị trí:** ${pageStr} (Tập ${volume})`);
    citationList.push({ document: fileName, lesson: lessonName, position: pageStr, volume: String(volume) });
  });
}

return {
  selected_agent: selectedAgent,
  requires_rag: requiresRag,
  predicted_intents: predictedIntents,
  joined_context: contextTexts.join('\n\n'),
  citation_block: citations.join('\n'),
  citation_list: citationList,
  retrieval_failed: retrievalFailed
};
